import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, statSync } from 'node:fs';
import { FIXTURE_DIR, ROOT } from './paths.ts';

const BUILDERS = `${ROOT}/packages/testkit/src/fixtures`;

/**
 * Fixtures are generated by the same code the headless suites use (SPEC §15, no binary fixtures in git).
 * They are rebuilt when a fixture builder changed after the files were written.
 */
export default function globalSetup(): void {
  const marker = `${FIXTURE_DIR}/photo-1.jpg`;
  const newest = Math.max(...readdirSync(BUILDERS).map((f) => statSync(`${BUILDERS}/${f}`).mtimeMs));
  const fresh = existsSync(marker) && statSync(marker).mtimeMs >= newest;
  if (fresh && !process.env.FOLIO_REBUILD_FIXTURES) return;
  execFileSync('pnpm', ['-s', 'cli', 'fixtures', '--out', FIXTURE_DIR], { cwd: ROOT, stdio: 'inherit' });
}
